        public const string Weapon="Assets/IronRequiem/Prefabs/Weapons/Weapon_BigBot_Burst_v10.prefab",Enemy="Assets/IronRequiem/Prefabs/Enemies/BigBot_Burst_v10.prefab",Pickup="Assets/IronRequiem/Prefabs/Weapons/BigBot_BurstPickup_v10.prefab",Projectile="Assets/IronRequiem/Prefabs/Projectiles/Projectile_BigBot_Burst_v10.prefab",Flash="Assets/IronRequiem/Prefabs/VFX/BigBot_BurstMuzzle_v10.prefab",Lab="Assets/IronRequiem/Scenes/BigBotBurstLab.unity",Reports="Tools/IronRequiem/Reports/BigBotBurst";
        const string Queue="Tools/IronRequiem/Requests/bigbot-burst.txt",Key="IRON.BigBotBurst";static readonly DateTime LoadedAt=DateTime.UtcNow;static TestRunnerApi api;
        static BigBotBurstAuthoring(){EditorApplication.update+=Tick;if(SessionState.GetBool(Key,false))EditorApplication.delayCall+=Register;}
        static bool Dirty()=>Enumerable.Range(0,SceneManager.sceneCount).Any(i=>SceneManager.GetSceneAt(i).isDirty);
        static void Register(){if(!api){api=ScriptableObject.CreateInstance<TestRunnerApi>();api.RegisterCallbacks(new Results());}}
        static void Tick()
        {
            if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SessionState.GetBool(Key,false))return;
            if(SessionState.GetBool(Key+".restore",false)){SessionState.EraseBool(Key+".restore");if(!Dirty())EditorSceneManager.OpenScene(Lab);IronRequiemSetupTools.WriteAudit();}
            if(!File.Exists(Queue))return;foreach(var p in new[]{"Assets/IronRequiem/Editor/BigBotBurstAuthoring.cs","Assets/IronRequiem/Tests/PlayMode/BigBotBurstTests.cs","Assets/IronRequiem/Scripts/Weapons/CannonBurstShot.cs","Assets/IronRequiem/Scripts/AI/BigBotCombat.cs"})if(File.GetLastWriteTimeUtc(p)>LoadedAt)return;
            var op=File.ReadAllText(Queue).Trim();File.Delete(Queue);Directory.CreateDirectory(Reports);try{if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");if(op=="build"){Build();File.WriteAllText(Queue,"test");}else if(op=="test"){Register();SessionState.SetBool(Key,true);api.Execute(new ExecutionSettings(new Filter{testMode=TestMode.PlayMode,testNames=new[]{"IronRequiem.Tests.BigBotBurstTests"}}));}else throw new InvalidOperationException("Unknown burst action");}catch(Exception e){File.WriteAllText(Reports+"/error.txt",e.ToString());Debug.LogException(e);}
        }
        static void Variant(string source,string destination)
        {if(File.Exists(destination))throw new InvalidOperationException("Preserve existing "+destination);var scene=EditorSceneManager.NewPreviewScene();try{var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(source),scene);go.name=Path.GetFileNameWithoutExtension(destination);PrefabUtility.SaveAsPrefabAsset(go,destination);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
        static void Set(SerializedObject data,string field,float value){var p=data.FindProperty(field);if(p.propertyType==SerializedPropertyType.Boolean)p.boolValue=value!=0;else if(p.propertyType==SerializedPropertyType.Integer)p.intValue=(int)value;else p.floatValue=value;}
        static Transform Named(GameObject go,string name)=>go.GetComponentsInChildren<Transform>(true).Single(t=>t.name==name);
        static void Build()
        {
            Variant("Assets/FPS/Prefabs/VFX/VFX_MuzzleFlashBlue.prefab",Flash);var go=PrefabUtility.LoadPrefabContents(Flash);try{go.transform.SetLocalPositionAndRotation(Vector3.zero,Quaternion.identity);foreach(var ps in go.GetComponentsInChildren<ParticleSystem>(true)){ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.loop=false;main.playOnAwake=true;main.duration=.08f;main.startLifetime=new ParticleSystem.MinMaxCurve(.035f,.075f);main.maxParticles=12;main.startSize=new ParticleSystem.MinMaxCurve(.035f,.07f);main.startSpeed=new ParticleSystem.MinMaxCurve(1.8f,3);main.simulationSpace=ParticleSystemSimulationSpace.Local;main.stopAction=ParticleSystemStopAction.Destroy;var emission=ps.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,6)});var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=12;shape.radius=.02f;var lights=ps.lights;lights.enabled=false;}foreach(var light in go.GetComponentsInChildren<Light>(true))light.gameObject.SetActive(false);PrefabUtility.SaveAsPrefabAsset(go,Flash);}finally{PrefabUtility.UnloadPrefabContents(go);}
            var oldWeapon=AssetDatabase.LoadAssetAtPath<GameObject>(BigBotBazookaAuthoring.Weapon).GetComponent<WeaponController>();Variant(AssetDatabase.GetAssetPath(oldWeapon.ProjectilePrefab),Projectile);go=PrefabUtility.LoadPrefabContents(Projectile);try{var charged=go.GetComponent<ChargedProjectileDamage>();if(charged){if(charged.EnergyVisual)charged.EnergyVisual.localScale=Vector3.one*.08f;Object.DestroyImmediate(charged);}var p=go.GetComponent<ProjectileStandard>();p.Damage=25;p.Radius=.04f;var trail=go.GetComponent<TrailRenderer>();if(trail)trail.widthMultiplier=.08f;PrefabUtility.SaveAsPrefabAsset(go,Projectile);}finally{PrefabUtility.UnloadPrefabContents(go);}
            Variant("Assets/FPS/Prefabs/Weapons/Weapon_Blaster.prefab",Weapon);go=PrefabUtility.LoadPrefabContents(Weapon);var old=PrefabUtility.LoadPrefabContents(BigBotBazookaAuthoring.Weapon);try
            {
                var w=go.GetComponent<WeaponController>();var source=old.GetComponent<WeaponController>();var root=w.WeaponRoot;var muzzle=w.WeaponMuzzle;EditorUtility.CopySerialized(source,w);w.WeaponRoot=root;w.WeaponMuzzle=muzzle;w.WeaponAnimator=null;w.EjectionPort=null;w.ProjectilePrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Projectile).GetComponent<ProjectileBase>();w.DelayBetweenShots=.05f;w.MuzzleFlashPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Flash);w.UnparentMuzzleFlash=false;
                var cells=go.GetComponent<WeaponFuelCellHandler>();if(cells)Object.DestroyImmediate(cells);var heat=go.GetComponent<OverheatBehavior>();if(heat)Object.DestroyImmediate(heat);foreach(Transform child in root.transform)child.gameObject.SetActive(false);
                foreach(var name in new[]{"BigBot_EquippedCannon","Attachment"}){var original=Named(old,name);var copy=Object.Instantiate(original.gameObject,root.transform);copy.name=name;copy.transform.localPosition=original.localPosition;copy.transform.localRotation=original.localRotation;copy.transform.localScale=original.localScale;copy.SetActive(true);}
                muzzle.localPosition=old.transform.InverseTransformPoint(source.WeaponMuzzle.position);muzzle.localRotation=Quaternion.Inverse(old.transform.rotation)*source.WeaponMuzzle.rotation;muzzle.localScale=Vector3.one;go.AddComponent<CannonBurstShot>();PrefabUtility.SaveAsPrefabAsset(go,Weapon);
            }finally{PrefabUtility.UnloadPrefabContents(go);PrefabUtility.UnloadPrefabContents(old);}
            Variant(BigBotChargeReferenceAuthoring.Pickup,Pickup);go=PrefabUtility.LoadPrefabContents(Pickup);try{go.GetComponent<StolenCannon>().Configure(AssetDatabase.LoadAssetAtPath<GameObject>(Weapon).GetComponent<WeaponController>());PrefabUtility.SaveAsPrefabAsset(go,Pickup);}finally{PrefabUtility.UnloadPrefabContents(go);}
            Variant(BigBotChargeReferenceAuthoring.Enemy,Enemy);go=PrefabUtility.LoadPrefabContents(Enemy);try{var combat=go.GetComponent<BigBotCombat>();var data=new SerializedObject(combat);foreach(var pair in new[]{("alternatingBursts",1f),("normalBurstCount",3f),("normalBurstInterval",.18f),("normalBurstPause",1.5f),("emergencyBurstCount",3f),("emergencyBurstInterval",.12f),("emergencyBurstPause",.9f)})Set(data,pair.Item1,pair.Item2);data.ApplyModifiedPropertiesWithoutUndo();foreach(var cannon in combat.Cannons){cannon.DelayBetweenShots=.05f;cannon.MuzzleFlashPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Flash);cannon.UnparentMuzzleFlash=false;}go.GetComponent<BigBotDestruction>().ConfigureCollectibleCannon(AssetDatabase.LoadAssetAtPath<GameObject>(Pickup).GetComponent<StolenCannon>());PrefabUtility.SaveAsPrefabAsset(go,Enemy);}finally{PrefabUtility.UnloadPrefabContents(go);}
            if(File.Exists(Lab))throw new InvalidOperationException("Preserve lab");AssetDatabase.CopyAsset(BigBotChargeReferenceAuthoring.Lab,Lab);var scene=EditorSceneManager.OpenScene(Lab);var prior=Object.FindAnyObjectByType<BigBotCombat>().gameObject;var replacement=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Enemy),scene);replacement.transform.SetPositionAndRotation(prior.transform.position,prior.transform.rotation);replacement.transform.localScale=prior.transform.localScale;foreach(var route in Object.FindObjectsByType<Unity.FPS.AI.PatrolPath>())for(int i=0;i<route.EnemiesToAssign.Count;i++)if(route.EnemiesToAssign[i]==prior.GetComponent<Unity.FPS.AI.EnemyController>())route.EnemiesToAssign[i]=replacement.GetComponent<Unity.FPS.AI.EnemyController>();Object.DestroyImmediate(prior);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();
            File.WriteAllText(Reports+"/settings.txt","AI: 3 total explosive projectiles (not 3 per cannon), alternating 0/1; 10 damage each, 30/burst; normal .18 s and 1.5 s pause; emergency .12 s and .9 s pause. Existing .7 s anticipation, locked aim throughout burst, 22 m/s, 48 m travel, 22 m attack and 36 m detection unchanged. Upper-bound DPS with warning: 30/2.56=11.72 normal; 30/1.84=16.30 emergency. Actual dodging/falloff reduces this; no 6-projectile doubled salvo. Stolen: fixed 25 damage, 2.6 m blast, 300 m/s, 3 shots at .18 s, 1.5 s pause, 12 energy/projectile from existing 100 capacity. Full burst 75 damage/36 energy. Existing critical OVERDRIVE cancels further shots. Fresh base variant has no CannonChargeShot, presentation or charge VFX references. T07 unchanged. Existing WeaponController owns every projectile, muzzle effect and recoil; no timed shooting outside manager input gate.");IronRequiemSetupTools.WriteAudit();
        }
        sealed class Results:IErrorCallbacks
        {public void RunStarted(ITestAdaptor t){}public void TestStarted(ITestAdaptor t){}public void TestFinished(ITestResultAdaptor t){}public void OnError(string m){SessionState.EraseBool(Key);File.WriteAllText(Reports+"/runner-error.txt",m);}public void RunFinished(ITestResultAdaptor r){if(!SessionState.GetBool(Key,false))return;SessionState.EraseBool(Key);TestRunnerApi.SaveResultToFile(r,Reports+"/play.xml");File.WriteAllText(Reports+"/status.txt",r.ResultState+" passed="+r.PassCount+" failed="+r.FailCount);SessionState.SetBool(Key+".restore",true);}}
    }
